    10	public class Database {
    11	    private final HikariDataSource dataSource;
    12	
    13	    public Database(String url, String user, String password) {
    14	        HikariConfig config = new HikariConfig();
    15	        config.setJdbcUrl(url);
    16	        config.setUsername(user);
    17	        config.setPassword(password);
    18	        config.setMaximumPoolSize(10);
    19	        this.dataSource = new HikariDataSource(config);
    20	    }
    21	
    22	    public void init() {
    23	        try (Connection conn = dataSource.getConnection()) {
    24	            createSchema(conn);
    25	        } catch (SQLException e) {
    26	            throw new RuntimeException("Erro ao inicializar banco de dados", e);
    27	        }
    28	    }
    29	
    30	    private void createSchema(Connection conn) throws SQLException {
    31	        String[] statements = {
    32	                "CREATE TABLE IF NOT EXISTS rooms (" +
    33	                        "number INTEGER PRIMARY KEY," +
    34	                        "type VARCHAR(20) NOT NULL," +
    35	                        "capacity INTEGER NOT NULL," +
    36	                        "nightly_rate NUMERIC(10, 2) NOT NULL" +
    37	                        ")",
    38	
    39	                "CREATE TABLE IF NOT EXISTS reservations (" +
    40	                        "id SERIAL PRIMARY KEY," +
    41	                        "room_number INTEGER NOT NULL," +
    42	                        "guest_name VARCHAR(255) NOT NULL," +
    43	                        "guest_email VARCHAR(255) NOT NULL," +
    44	                        "guest_cpf VARCHAR(14) NOT NULL," +
    45	                        "check_in DATE NOT NULL," +
    46	                        "check_out DATE NOT NULL," +
    47	                        "guests INTEGER NOT NULL," +
    48	                        "rate_plan VARCHAR(20) NOT NULL," +
    49	                        "nights INTEGER NOT NULL," +
    50	                        "subtotal NUMERIC(10, 2) NOT NULL," +
    51	                        "discount NUMERIC(10, 2) NOT NULL," +
    52	                        "total NUMERIC(10, 2) NOT NULL," +
    53	                        "status VARCHAR(20) NOT NULL," +
    54	                        "amount_paid NUMERIC(10, 2) NOT NULL DEFAULT 0," +
    55	                        "refund NUMERIC(10, 2)," +
    56	                        "FOREIGN KEY (room_number) REFERENCES rooms(number)" +
    57	                        ")",
    58	
    59	                "CREATE TABLE IF NOT EXISTS messages (" +
    60	                        "id SERIAL PRIMARY KEY," +
    61	                        "channel VARCHAR(20) NOT NULL," +
    62	                        "\"to\" VARCHAR(255) NOT NULL," +
    63	                        "subject VARCHAR(500) NOT NULL," +
    64	                        "body TEXT NOT NULL" +
    65	                        ")",
    66	
    67	                "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (101, 'STANDARD', 2, 249.90) " +
    68	                        "ON CONFLICT DO NOTHING",
    69	                "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (102, 'STANDARD', 2, 249.90) " +
    70	                        "ON CONFLICT DO NOTHING",
    71	                "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (201, 'DELUXE', 3, 389.90) " +
    72	                        "ON CONFLICT DO NOTHING",
    73	                "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (202, 'DELUXE', 3, 389.90) " +
    74	                        "ON CONFLICT DO NOTHING",
    75	                "INSERT INTO rooms (number, type, capacity, nightly_rate) VALUES (301, 'SUITE', 4, 579.90) " +
    76	                        "ON CONFLICT DO NOTHING"
    77	        };
    78	
    79	        for (String sql : statements) {
    80	            try (Statement stmt = conn.createStatement()) {
    81	                stmt.executeUpdate(sql);
    82	            }
    83	        }
    84	    }
    85	
    86	    public Connection getConnection() throws SQLException {
    87	        return dataSource.getConnection();
    88	    }
    89	
    90	    public void close() {
    91	        dataSource.close();
    92	    }
    93	}
