    33	
    34	    public void createReservation(Context ctx) {
    35	        try {
    36	            CreateReservationRequest body = ctx.bodyAsClass(CreateReservationRequest.class);
    37	
    38	            // Validação de campos obrigatórios
    39	            if (body.roomNumber == 0 || body.guestName == null || body.guestEmail == null ||
    40	                    body.guestCpf == null || body.checkIn == null || body.checkOut == null ||
    41	                    body.guests == 0 || body.ratePlan == null) {
    42	                ctx.status(400);
    43	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Faltam campos obrigatórios"));
    44	                return;
    45	            }
    46	
    47	            int roomNumber = body.roomNumber;
    48	            String guestName = body.guestName;
    49	            String guestEmail = body.guestEmail;
    50	            String guestCpf = body.guestCpf;
    51	            LocalDate checkIn = body.checkIn;
    52	            LocalDate checkOut = body.checkOut;
    53	            int guests = body.guests;
    54	            String ratePlan = body.ratePlan;
    55	
    56	            // Validação de quarto
    57	            Room room = roomService.getRoomByNumber(roomNumber);
    58	            if (room == null) {
    59	                ctx.status(404);
    60	                ctx.json(new ErrorResponse("ROOM_NOT_FOUND", "Quarto não encontrado"));
    61	                return;
    62	            }
    63	
    64	            // Validação de datas
    65	            if (!checkOut.isAfter(checkIn)) {
    66	                ctx.status(400);
    67	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Data de saída deve ser após data de entrada"));
    68	                return;
    69	            }
    70	
    71	            // Validação de hóspedes
    72	            if (guests < 1) {
    73	                ctx.status(400);
    74	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Número de hóspedes deve ser pelo menos 1"));
    75	                return;
    76	            }
    77	
    78	            if (guests > room.capacity) {
    79	                ctx.status(422);
    80	                ctx.json(new ErrorResponse("CAPACITY_EXCEEDED", "Número de hóspedes excede a capacidade do quarto"));
    81	                return;
    82	            }
    83	
    84	            // Validação de disponibilidade
    85	            if (!reservationService.isRoomAvailable(roomNumber, checkIn, checkOut)) {
    86	                ctx.status(409);
    87	                ctx.json(new ErrorResponse("ROOM_UNAVAILABLE", "Quarto não está disponível para as datas selecionadas"));
    88	                return;
    89	            }
    90	
    91	            Reservation reservation = reservationService.createReservation(
    92	                    roomNumber, guestName, guestEmail, guestCpf, checkIn, checkOut, guests, ratePlan, room);
    93	
    94	            ctx.status(201);
    95	            ctx.json(new ReservationDTO(reservation));
    96	        } catch (DateTimeParseException e) {
    97	            ctx.status(400);
    98	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Formato de data inválido, use yyyy-MM-dd"));
    99	        } catch (Exception e) {
   100	            ctx.status(400);
   101	            ctx.json(new ErrorResponse("INVALID_REQUEST", "Requisição inválida: " + e.getMessage()));
   102	        }
   103	    }
