   105	    public void getReservation(Context ctx) {
   106	        try {
   107	            long id = ctx.pathParamAsClass("id", Long.class).get();
   108	            Reservation reservation = reservationService.getReservationById(id);
   109	
   110	            if (reservation == null) {
   111	                ctx.status(404);
   112	                ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
   113	                return;
   114	            }
   115	
   116	            ctx.json(new ReservationDTO(reservation));
   117	        } catch (Exception e) {
   118	            ctx.status(404);
   119	            ctx.json(new ErrorResponse("RESERVATION_NOT_FOUND", "Reserva não encontrada"));
   120	        }
   121	    }
   122	
   123	    public void confirmReservation(Context ctx) {
   124	        try {
   125	            long id = ctx.pathParamAsClass("id", Long.class).get();
   126	            ConfirmReservationRequest body = ctx.bodyAsClass(ConfirmReservationRequest.class);
   127	
   128	            if (body.amountPaid == null) {
   129	                ctx.status(400);
   130	                ctx.json(new ErrorResponse("INVALID_REQUEST", "Campo amountPaid é obrigatório"));
   131	                return;
   132	            }
   133	
   134	            Reservation reservation = reservationService.getReservationById(id);
   135	            if (reservation == null) {
   136	                ctx.status(404);
