   176	            String sql = "SELECT rate_plan, COUNT(*) as count, COALESCE(SUM(amount_paid - COALESCE(refund, 0)), 0) as revenue " +
   177	                    "FROM reservations " +
   178	                    "WHERE EXTRACT(YEAR FROM check_in) = " + month.getYear() +
   179	                    " AND EXTRACT(MONTH FROM check_in) = " + month.getMonthValue() +
   180	                    " AND status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT', 'CANCELLED') " +
   181	                    "GROUP BY rate_plan";
   182	
   183	            ResultSet rs = stmt.executeQuery(sql);
   184	
   185	            while (rs.next()) {
   186	                String ratePlan = rs.getString("rate_plan");
   187	                int count = rs.getInt("count");
   188	                BigDecimal revenue = rs.getBigDecimal("revenue");
   189	
   190	                if ("STANDARD".equals(ratePlan)) {
   191	                    standardCount = count;
