   204	            BigDecimal totalRevenue = standardRevenue.add(nonRefundableRevenue);
   205	            int totalCount = standardCount + nonRefundableCount;
   206	            csv.append("total,").append(totalCount).append(",")
   207	                    .append(FormatUtils.formatCurrencyCSV(totalRevenue)).append("\n");
   208	
   209	        } catch (Exception e) {
