    10	public class FormatUtils {
    11	    private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("dd/MM/yyyy");
    12	    private static final DateTimeFormatter DATE_ISO_FORMATTER = DateTimeFormatter.ofPattern("yyyy-MM-dd");
    13	    private static final DecimalFormat CURRENCY_FORMATTER;
    14	
    15	    static {
    16	        DecimalFormatSymbols symbols = new DecimalFormatSymbols(new Locale("pt", "BR"));
    17	        symbols.setDecimalSeparator(',');
    18	        symbols.setGroupingSeparator('.');
    19	        CURRENCY_FORMATTER = new DecimalFormat("#,##0.00", symbols);
    20	        CURRENCY_FORMATTER.setMinimumFractionDigits(2);
    21	    }
    22	
    23	    public static String formatDate(LocalDate date) {
    24	        return date.format(DATE_FORMATTER);
    25	    }
    26	
    27	    public static String formatDateIso(LocalDate date) {
    28	        return date.format(DATE_ISO_FORMATTER);
    29	    }
    30	
    31	    public static String formatCurrency(BigDecimal value) {
    32	        return "R$ " + CURRENCY_FORMATTER.format(value);
    33	    }
    34	
    35	    public static String formatCurrencyCSV(BigDecimal value) {
    36	        return value.toPlainString();
    37	    }
    38	
    39	    public static String formatCPF(String cpf) {
    40	        if (cpf == null || cpf.length() != 11) {
    41	            return cpf;
    42	        }
    43	        return cpf.substring(0, 3) + "." + cpf.substring(3, 6) + "." +
    44	               cpf.substring(6, 9) + "-" + cpf.substring(9);
    45	    }
    46	
    47	    public static String parseCPF(String cpf) {
    48	        if (cpf == null) {
    49	            return null;
    50	        }
    51	        return cpf.replaceAll("[^0-9]", "");
    52	    }
    53	}
