     1	package com.pousada.utils;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.Month;
     7	
     8	public class PricingUtils {
     9	    private static final BigDecimal PEAK_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
    10	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT_RATE = BigDecimal.valueOf(0.15);
    11	
    12	    public static boolean isPeakSeason(LocalDate date) {
    13	        Month month = date.getMonth();
    14	        int day = date.getDayOfMonth();
    15	
    16	        if (month == Month.JULY) {
    17	            return true;
    18	        }
    19	        if (month == Month.DECEMBER) {
    20	            return day >= 15;
    21	        }
    22	        return month == Month.JANUARY || month == Month.FEBRUARY;
    23	    }
    24	
    25	    public static BigDecimal roundToNearest(BigDecimal value) {
    26	        return value.setScale(2, RoundingMode.HALF_EVEN);
    27	    }
    28	
    29	    public static BigDecimal calculateNightlyRate(BigDecimal baseRate, LocalDate date) {
    30	        if (isPeakSeason(date)) {
    31	            return roundToNearest(baseRate.multiply(PEAK_SEASON_MULTIPLIER));
    32	        }
    33	        return baseRate;
    34	    }
    35	
    36	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    37	        BigDecimal subtotal = BigDecimal.ZERO;
    38	        LocalDate current = checkIn;
    39	        while (current.isBefore(checkOut)) {
    40	            subtotal = subtotal.add(calculateNightlyRate(baseRate, current));
    41	            current = current.plusDays(1);
    42	        }
    43	        return subtotal;
    44	    }
    45	
    46	    public static BigDecimal calculateDiscount(String ratePlan, BigDecimal subtotal) {
    47	        if ("NON_REFUNDABLE".equals(ratePlan)) {
    48	            return roundToNearest(subtotal.multiply(NON_REFUNDABLE_DISCOUNT_RATE));
    49	        }
    50	        return BigDecimal.ZERO;
    51	    }
    52	
    53	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    54	        return roundToNearest(subtotal.subtract(discount));
    55	    }
    56	
    57	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    58	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    59	    }
    60	}
