    10	import static org.junit.Assert.*;
    11	
    12	public class ReservationTest {
    13	    @Test
    14	    public void testPeakSeasonDetection() {
    15	        // July is always peak season
    16	        assertTrue(PricingUtils.isPeakSeason(LocalDate.parse("2027-07-10")));
    17	
    18	        // December 15+ is peak season
    19	        assertTrue(PricingUtils.isPeakSeason(LocalDate.parse("2027-12-15")));
    20	        assertFalse(PricingUtils.isPeakSeason(LocalDate.parse("2027-12-14")));
    21	
    22	        // January and February are peak season
    23	        assertTrue(PricingUtils.isPeakSeason(LocalDate.parse("2027-01-01")));
    24	        assertTrue(PricingUtils.isPeakSeason(LocalDate.parse("2027-02-28")));
    25	
    26	        // April is not peak season
    27	        assertFalse(PricingUtils.isPeakSeason(LocalDate.parse("2027-04-01")));
    28	    }
    29	
    30	    @Test
    31	    public void testNightlyRateCalculation() {
    32	        BigDecimal baseRate = new BigDecimal("249.90");
    33	
    34	        // Peak season: 249.90 * 1.20 = 299.88
    35	        BigDecimal peakRate = PricingUtils.calculateNightlyRate(baseRate, LocalDate.parse("2027-07-10"));
    36	        assertEquals(new BigDecimal("299.88"), peakRate);
    37	
    38	        // Off-season: 249.90
    39	        BigDecimal offSeasonRate = PricingUtils.calculateNightlyRate(baseRate, LocalDate.parse("2027-04-01"));
    40	        assertEquals(new BigDecimal("249.90"), offSeasonRate);
    41	    }
    42	
    43	    @Test
    44	    public void testSubtotalCalculation() {
    45	        BigDecimal baseRate = new BigDecimal("249.90");
    46	        LocalDate checkIn = LocalDate.parse("2027-07-10");
    47	        LocalDate checkOut = LocalDate.parse("2027-07-12");
    48	
    49	        // 2 nights in July: 299.88 * 2 = 599.76
    50	        BigDecimal subtotal = PricingUtils.calculateSubtotal(baseRate, checkIn, checkOut);
    51	        assertEquals(new BigDecimal("599.76"), subtotal);
    52	    }
    53	
    54	    @Test
    55	    public void testDiscountCalculation() {
    56	        BigDecimal subtotal = new BigDecimal("599.76");
    57	
    58	        // Standard plan: no discount
    59	        BigDecimal standardDiscount = PricingUtils.calculateDiscount("STANDARD", subtotal);
    60	        assertEquals(BigDecimal.ZERO, standardDiscount);
    61	
    62	        // Non-refundable: 15% discount = 599.76 * 0.15 = 89.964 -> 89.96
    63	        BigDecimal nonRefundableDiscount = PricingUtils.calculateDiscount("NON_REFUNDABLE", subtotal);
    64	        assertEquals(new BigDecimal("89.96"), nonRefundableDiscount);
